using HPD.Agent.Audio.Runtime.Output;
using HPD.Agent.Authority;

namespace HPD.Agent.LiveAudio.Contracts.Tests;

public sealed class OutputTtsSinkPipelineTests
{
    [Fact] public void Segmented_and_push_families_produce_concrete_generated_evidence(){foreach(var family in new[]{OutputSynthesisFamily.SegmentedPcm,OutputSynthesisFamily.PushPcm}){var s=State();var r=Assert.IsType<OutputPipelineResult.Applied>(OutputTtsSinkPipeline.Generate(s,new(OperationId.Create(),family,"hello",20),new DeterministicPcmSynthesisProvider(family),16));Assert.Equal(5,r.State.Status.GeneratedUntil);}}
    [Fact] public async Task Generated_sent_played_and_heard_are_settled_by_distinct_effects(){var s=Generated();s=A(await OutputTtsSinkPipeline.SendAsync(s,new(OperationId.Create(),5),new ManualOutputSinkEffectPort(),16));s=A(await OutputTtsSinkPipeline.PlayAsync(s,new(OperationId.Create(),4),new ManualOutputSinkEffectPort(),16));s=A(await OutputTtsSinkPipeline.HearAsync(s,new(OperationId.Create(),3),new ManualOutputSinkEffectPort(),16));Assert.Equal((5L,5L,4L,3L),(s.Status.GeneratedUntil,s.Status.SentUntil,s.Status.PlayedUntil,s.Status.HeardUntil));}
    [Fact] public async Task Sink_refusal_preserves_every_output_axis(){var s=Generated();var r=Assert.IsType<OutputPipelineResult.EffectRefused>(await OutputTtsSinkPipeline.SendAsync(s,new(OperationId.Create(),5),new ManualOutputSinkEffectPort(_=>new OutputSinkEffectResult.Refused(new BoundedAscii("sink-refused"))),16));Assert.Same(s,r.State);Assert.Equal(0,r.State.Status.SentUntil);}
    [Fact] public async Task Unknown_sink_outcome_cannot_be_promoted_to_sent(){var s=Generated();var r=Assert.IsType<OutputPipelineResult.OutcomeUnknown>(await OutputTtsSinkPipeline.SendAsync(s,new(OperationId.Create(),5),new ManualOutputSinkEffectPort(_=>new OutputSinkEffectResult.OutcomeUnknown(new BoundedAscii("sink-outcome-unknown"))),16));Assert.Equal(0,r.State.Status.SentUntil);}
    [Fact] public async Task Sink_acknowledgement_cannot_skip_upstream_authority(){var s=Generated();var r=Assert.IsType<OutputPipelineResult.Rejected>(await OutputTtsSinkPipeline.PlayAsync(s,new(OperationId.Create(),1),new ManualOutputSinkEffectPort(),16));Assert.Equal("output-transition-invalid",r.SafeCode.ToString());}
    [Fact] public async Task Mismatched_sink_receipt_cannot_advance_authority(){var s=Generated();var requested=new OutputSinkEffect.Send(OperationId.Create(),5);var other=new OutputSinkEffect.Send(OperationId.Create(),5);var r=Assert.IsType<OutputPipelineResult.Rejected>(await OutputTtsSinkPipeline.SendAsync(s,requested,new ManualOutputSinkEffectPort(_=>new OutputSinkEffectResult.Acknowledged(other)),16));Assert.Equal("output-sink-receipt-invalid",r.SafeCode.ToString());Assert.Equal(0,r.State.Status.SentUntil);}
    [Fact] public void Asynchronous_provider_evidence_can_be_admitted_without_replaying_the_effect(){var s=State();var operation=OperationId.Create();var evidence=new OutputSynthesisEvidence(operation,OutputSynthesisFamily.PushPcm,4,Hash256.Compute(new byte[]{1,2,3,4}));var applied=Assert.IsType<OutputPipelineResult.Applied>(OutputTtsSinkPipeline.Generate(s,evidence,16));Assert.Equal(4,applied.State.Status.GeneratedUntil);Assert.Equal(operation,applied.Receipt.Command.OperationId);}
    private static OutputControllerState Generated()=>A(OutputTtsSinkPipeline.Generate(State(),new(OperationId.Create(),OutputSynthesisFamily.SegmentedPcm,"hello",20),new DeterministicPcmSynthesisProvider(OutputSynthesisFamily.SegmentedPcm),16));
    private static OutputControllerState State(){var s=new SessionAuthorityStampV1(RuntimeGenerationId.Create(),LiveSessionId.Create());var o=OutputGenerationId.Create();var a=ExpectedAuthorityVectorV1.Create(s,[new AuthorityAxisValueV1.Output(o)]);return new(new OutputPlan(OperationId.Create(),o,a,20),new(0,0,0,0,0,false));}
    private static OutputControllerState A(OutputPipelineResult r)=>Assert.IsType<OutputPipelineResult.Applied>(r).State;
}
